<?php if ($visits === []): ?><div class="patient-empty-state"><i class="bi bi-clipboard2-pulse" aria-hidden="true"></i><strong>No visits found</strong><span>Recorded consultations will appear here.</span></div><?php else: ?><div class="patient-visits-grid"><?php foreach ($visits as $visit): ?><article class="patient-visit-card"><div class="patient-visit-card-header"><div><span class="patient-eyebrow">Visit</span><h3 title="<?= esc($visit['consultation_number'], 'attr') ?>"><?= esc($visit['consultation_number']) ?></h3></div><span class="badge patient-status-badge patient-status-<?= esc($visit['status']) ?>"><?= esc($visit['status_label']) ?></span></div><p class="patient-visit-card-doctor"><strong>Dr. <?= esc(trim(($visit['doctor_first_name'] ?? '') . ' ' . ($visit['doctor_last_name'] ?? ''))) ?></strong><small><?= esc($visit['specialization'] ?: 'Not recorded') ?></small></p><dl class="patient-visit-card-details"><div><dt>Date / time</dt><dd><?= esc($visit['visit_date_display']) ?> · <?= esc($visit['visit_time_display']) ?></dd></div><div><dt>Service</dt><dd title="<?= esc($visit['service_display'], 'attr') ?>"><?= esc($visit['service_display']) ?></dd></div><div><dt>Appointment</dt><dd><?= esc($visit['appointment_number'] ?: 'Not linked') ?></dd></div><div><dt>Records</dt><dd><?= ! empty($visit['prescription_id']) ? 'Prescription' : 'No prescription' ?> · <?= ! empty($visit['invoice_id']) ? 'Invoice' : 'No invoice' ?></dd></div></dl><p class="patient-card-meta"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i>Updated <?= esc($visit['updated_at'] ?? '—') ?></p><div class="patient-visit-card-actions"><div class="dropdown"><button class="btn btn-sm btn-primary dropdown-toggle" type="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">More Actions</button><div class="dropdown-menu dropdown-menu-right"><button class="dropdown-item patient-visit-view" type="button" data-id="<?= (int) $visit['id'] ?>" data-toggle="modal" data-target="#patient-visit-detail-modal">View visit</button></div></div></div></article><?php endforeach; ?></div><?php endif; ?>
